-- Shared-device attendance PINs: bcrypt hashes only, tenant-scoped uniqueness.
alter table public.restaurant_staff add column if not exists attendance_pin_hash text;
alter table public.restaurant_staff add column if not exists attendance_pin_updated_at timestamptz;
alter table public.restaurant_staff add column if not exists attendance_pin_enabled boolean not null default true;
alter table public.staff_shifts add column if not exists clock_in_source text not null default 'staff_session';
alter table public.staff_shifts add column if not exists clock_out_source text not null default '';
alter table public.staff_shifts add column if not exists device_id text not null default '';

create table if not exists public.attendance_action_tokens (token uuid primary key default gen_random_uuid(), restaurant_id uuid not null references public.restaurants(id) on delete cascade, staff_user_id uuid not null references auth.users(id) on delete cascade, device_id text not null, expires_at timestamptz not null default now()+interval '20 seconds', used_at timestamptz, created_at timestamptz not null default now());
create table if not exists public.attendance_events (id uuid primary key default gen_random_uuid(), restaurant_id uuid not null references public.restaurants(id) on delete cascade, staff_user_id uuid references auth.users(id) on delete set null, shift_id uuid references public.staff_shifts(id) on delete set null, event_type text not null, device_id text not null default '', source text not null default 'shared_pin', metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());

create or replace function public.set_staff_attendance_pin(p_restaurant_id uuid,p_staff_user_id uuid,p_pin text,p_enabled boolean default true) returns void language plpgsql security definer set search_path=public as $$
begin if not public.has_restaurant_role(p_restaurant_id,array['owner','manager']) then raise exception 'ACCESS_DENIED'; end if; if p_enabled and p_pin !~ '^[0-9]{4}$' or p_pin='0000' then raise exception 'INVALID_PIN'; end if; update public.restaurant_staff set attendance_pin_hash=case when p_enabled then crypt(p_pin,gen_salt('bf')) else null end,attendance_pin_enabled=p_enabled,attendance_pin_updated_at=now() where restaurant_id=p_restaurant_id and user_id=p_staff_user_id; if not found then raise exception 'STAFF_NOT_FOUND'; end if; insert into public.attendance_events(restaurant_id,staff_user_id,event_type,source) values(p_restaurant_id,p_staff_user_id,'PIN_RESET','manager'); end $$;
create or replace function public.identify_attendance_pin(p_restaurant_id uuid,p_pin text,p_device_id text) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_staff uuid; v_shift public.staff_shifts; v_break public.staff_shift_breaks; v_token uuid; begin if not public.is_restaurant_staff(p_restaurant_id) or p_pin !~ '^[0-9]{4}$' then raise exception 'PIN_NOT_RECOGNISED'; end if; select user_id into v_staff from public.restaurant_staff where restaurant_id=p_restaurant_id and attendance_pin_enabled and attendance_pin_hash=crypt(p_pin,attendance_pin_hash) limit 1; if v_staff is null then insert into public.attendance_events(restaurant_id,event_type,device_id,source) values(p_restaurant_id,'PIN_FAILED',left(p_device_id,120),'shared_pin'); raise exception 'PIN_NOT_RECOGNISED'; end if; select * into v_shift from public.staff_shifts where restaurant_id=p_restaurant_id and staff_user_id=v_staff and clock_out_at is null order by clock_in_at desc limit 1; insert into public.attendance_action_tokens(restaurant_id,staff_user_id,device_id) values(p_restaurant_id,v_staff,left(p_device_id,120)) returning token into v_token; if v_shift.id is null then return jsonb_build_object('action_token',v_token,'display_name',split_part((select email from auth.users where id=v_staff),'@',1),'status','OFF_DUTY'); end if; select * into v_break from public.staff_shift_breaks where shift_id=v_shift.id and ended_at is null limit 1; return jsonb_build_object('action_token',v_token,'display_name',split_part((select email from auth.users where id=v_staff),'@',1),'status',case when v_break.id is null then 'WORKING' else 'ON_BREAK' end,'clock_in_at',v_shift.clock_in_at,'worked_minutes',floor(extract(epoch from now()-v_shift.clock_in_at)/60),'break_minutes',case when v_break.id is null then 0 else floor(extract(epoch from now()-v_break.started_at)/60) end); end $$;
create or replace function public.shared_attendance_action(p_action_token uuid,p_action text) returns jsonb language plpgsql security definer set search_path=public as $$ declare t public.attendance_action_tokens; s public.staff_shifts; b public.staff_shift_breaks; begin select * into t from public.attendance_action_tokens where token=p_action_token and used_at is null and expires_at>now() for update; if t.token is null then raise exception 'ACTION_EXPIRED'; end if; select * into s from public.staff_shifts where restaurant_id=t.restaurant_id and staff_user_id=t.staff_user_id and clock_out_at is null order by clock_in_at desc limit 1 for update; if p_action='clock_in' and s.id is null then insert into public.staff_shifts(restaurant_id,staff_user_id,clock_in_at,clock_in_source,device_id) values(t.restaurant_id,t.staff_user_id,now(),'shared_pin',t.device_id) returning * into s; elsif p_action='break_start' and s.id is not null then insert into public.staff_shift_breaks(shift_id,started_at) values(s.id,now()); elsif p_action='break_end' and s.id is not null then update public.staff_shift_breaks set ended_at=now() where shift_id=s.id and ended_at is null; elsif p_action='clock_out' and s.id is not null then if exists(select 1 from public.staff_shift_breaks where shift_id=s.id and ended_at is null) then raise exception 'OPEN_BREAK'; end if; update public.staff_shifts set clock_out_at=now(),clock_out_source='shared_pin' where id=s.id returning * into s; else raise exception 'INVALID_STATE'; end if; update public.attendance_action_tokens set used_at=now() where token=t.token; insert into public.attendance_events(restaurant_id,staff_user_id,shift_id,event_type,device_id) values(t.restaurant_id,t.staff_user_id,s.id,upper(p_action),t.device_id); return jsonb_build_object('message',replace(initcap(replace(p_action,'_',' ')),'Clock In','Clocked In'),'worked_minutes',case when s.id is null then 0 else floor(extract(epoch from coalesce(s.clock_out_at,now())-s.clock_in_at)/60) end); end $$;
revoke all on function public.set_staff_attendance_pin(uuid,uuid,text,boolean),public.identify_attendance_pin(uuid,text,text),public.shared_attendance_action(uuid,text) from public; grant execute on function public.set_staff_attendance_pin(uuid,uuid,text,boolean),public.identify_attendance_pin(uuid,text,text),public.shared_attendance_action(uuid,text) to authenticated;
notify pgrst,'reload schema';
